/*!40000 ALTER TABLE `sys_notice` DISABLE KEYS */;
REPLACE INTO `sys_notice` VALUES (1,'清远首个人工智能 OPC 生态社区正式揭牌运营','2',_binary '2026 年 8 月 1 日，清城区人工智能 OPC 生态社区在清远星谷科技园正式揭牌运营。从 7 月 11 日签约到揭牌仅用 21 天，被誉为\"清城速度\"。揭牌当天，塔链人工智能科技、南京世东智脑、正经点赞（清远）媒体科技等 6 家企业签约入驻，并与广东财贸职业学院、清远职业技术学院、广东岭南职业技术学院 3 所高校共建校外实践教学基地。','0','admin','2026-08-21 09:12:05','',NULL,'管理员'),(2,'首届人工智能 OPC 创客短视频创作大赛筹备启动','1',_binary '社区筹办 2026 首届人工智能 OPC 创客短视频创作大赛，并成立创客基金。社区将全面梳理文旅推广、政务科普、城市形象等领域的 AI 文创订单需求，联动星火深智等 AI 头部企业对接全国稳定内容订单，以订单和赛事吸引产业集聚。','0','admin','2026-08-21 09:12:05','',NULL,'管理员'),(3,'2026 年一季度上新微短剧中 AI 制作占比超 95%','1',_binary '行业数据显示，2025 年国内 AI 视频市场规模已突破 1200 亿元，预计 2030 年达 5800 亿元；2026 年一季度上新微短剧中，AI 制作占比已超过 95%。AI 微短剧、超级数字人、AIGC 内容创作等新业态正在成为数字经济的重要增长极。','0','admin','2026-08-21 09:12:05','',NULL,'管理员');
