REPLACE INTO `cms_article` VALUES (1,1,'清远首个人工智能 OPC 生态社区正式揭牌运营','2026 年 8 月 1 日，清城区人工智能 OPC 生态社区在清远星谷科技园正式揭牌运营，从签约到揭牌仅用 21 天，被誉为\"清城速度\"。','2026 年 8 月 1 日，清城区人工智能 OPC 生态社区在清远星谷科技园正式揭牌运营。从 7 月 11 日签约到揭牌仅用 21 天，被誉为\"清城速度\"。揭牌当天，塔链人工智能科技、南京世东智脑、正经点赞（清远）媒体科技等 6 家企业签约入驻，并与广东财贸职业学院、清远职业技术学院、广东岭南职业技术学院 3 所高校共建校外实践教学基地。',NULL,'数智游民创新工场','1','0',193,'2026-08-19 09:45:48','admin','2026-08-21 09:45:48','',NULL),(2,1,'2026 年一季度上新微短剧中 AI 制作占比超 95%','行业数据显示，2025 年国内 AI 视频市场规模已突破 1200 亿元，AI 微短剧、超级数字人等新业态正成为数字经济的重要增长极。','行业数据显示，2025 年国内 AI 视频市场规模已突破 1200 亿元，预计 2030 年达 5800 亿元；2026 年一季度上新微短剧中，AI 制作占比已超过 95%。AI 微短剧、超级数字人、AIGC 内容创作等新业态正在成为数字经济的重要增长极。',NULL,'数智游民创新工场','0','0',132,'2026-08-15 09:45:48','admin','2026-08-21 09:45:48','',NULL),(3,2,'AI 视频市场规模 1200 亿：一人公司主理人的入局机会','2025 年国内 AI 视频市场规模突破 1200 亿元，预计 2030 年达 5800 亿元。对 OPC 主理人而言，AI 内容制作正从\"尝鲜\"走向\"主业\"。','对 OPC（一人公司）主理人而言，AI 内容制作正从\"尝鲜\"走向\"主业\"：一人 + AI 即可完成剧本生成、视频制作、分发投放的全链路。社区面向主理人开放 AI 微短剧制作实战营、超级数字人实操课等课程，并提供订单对接支持，帮助个人创作者以更低门槛切入 AI 内容赛道。',NULL,'数智游民创新工场','0','0',99,'2026-08-17 09:45:48','admin','2026-08-21 09:45:48','',NULL),(4,3,'首届人工智能 OPC 创客短视频创作大赛筹备启动','社区筹办 2026 首届人工智能 OPC 创客短视频创作大赛，并成立创客基金，联动 AI 头部企业对接全国稳定内容订单。','社区筹办 2026 首届人工智能 OPC 创客短视频创作大赛，并成立创客基金。社区将全面梳理文旅推广、政务科普、城市形象等领域的 AI 文创订单需求，联动星火深智等 AI 头部企业对接全国稳定内容订单，以订单和赛事吸引产业集聚。',NULL,'数智游民创新工场','0','0',144,'2026-08-18 09:45:48','admin','2026-08-21 09:45:48','',NULL),(5,4,'毕业生 AI 实训营开营：本地高校学生迈出 OPC 创业第一步','面向本地高校毕业生与清远籍大学生的免费 OPC 创业实训营开营，结营学员将对接社区订单与入驻资源。','面向本地高校毕业生与清远籍大学生的免费 OPC 创业实训营正式开营。实训营覆盖一人公司注册、AI 工具矩阵、内容创作与获客实战全流程，结营学员将对接社区订单与入驻资源，迈出 OPC 创业的第一步。',NULL,'北江人工智能产教融合研究院','0','0',77,'2026-08-20 09:45:48','admin','2026-08-21 09:45:48','',NULL),(6,5,'《清远市人工智能创新发展行动方案（2026—2027年）》','清远市级人工智能纲领性文件，指导全市人工智能产业发展与 OPC 生态社区建设。','【政策名称】《清远市人工智能创新发展行动方案（2026—2027年）》\n【发文级别】清远市级\n【文号】清府办函〔2026〕...\n【状态】已出台\n【政策要点】清远市推进人工智能创新发展的纲领性文件，统筹全市人工智能产业布局，支持人工智能 OPC 生态社区建设。\n【原文链接】暂无直接官方链接，可通过清远市政府官网（http://www.gdqy.gov.cn）检索获取。',NULL,'数智游民创新工场','0','0',1,'2026-08-21 12:46:31','admin','2026-08-21 12:46:31','',NULL),(7,5,'清城区人工智能 OPC 生态社区战略合作框架协议','清城区政府与清远星链科技签署共建，21 天揭牌跑出\"清城速度\"。','【政策名称】清城区人工智能 OPC 生态社区战略合作框架协议\n【发文级别】清城区级\n【状态】已签署落地\n【政策要点】2026 年 7 月 11 日，清城区政府与清远市星链科技有限公司签署合作框架协议，共建清城区人工智能 OPC 生态社区（数智游民创新工场）；2026 年 8 月 1 日正式揭牌运营，从签约到揭牌仅用 21 天，被誉为\"清城速度\"。\n【媒体报道】南方日报：https://epaper.nfnews.com/nfdaily/html/202607/17/content_10175934.html；清远日报：https://www.qyrb.cn；中国日报：https://cnews.chinadaily.com.cn；新浪财经：https://finance.sina.cn',NULL,'数智游民创新工场','0','0',2,'2026-08-21 12:46:31','admin','2026-08-21 12:46:31','',NULL),(8,5,'清远高新区 AI OPC 登记注册绿色通道','一窗通办、一日办结，探索\"集群注册\"无需实体地址的注册模式。','【政策名称】清远高新区第十二期政企恳谈会——人工智能 OPC 登记注册绿色通道\n【发文级别】清远高新区\n【状态】已实施\n【政策要点】设立人工智能 OPC 登记注册\"明晰指引\"和\"绿色通道\"，实行\"一窗通办\"\"一日办结\"；探索\"集群注册\"等无需实体地址的注册模式，破解\"工位注册\"\"地址挂靠\"等落地堵点。\n【相关链接】https://www.qysed.cn',NULL,'数智游民创新工场','0','0',1,'2026-08-21 12:46:31','admin','2026-08-21 12:46:31','',NULL),(9,5,'清远市省市共建创业孵化基地（免租金）','入驻省市共建创业孵化基地享受 3-4 年免租金；OPC 项目最高 300㎡ 3 年免费。','【政策名称】清远市省市共建创业孵化基地（免租金）\n【发文级别】清远市级\n【状态】已实施\n【政策要点】入驻清远市省市共建创业孵化基地，享受 3 至 4 年免租金支持；对符合条件的数字游民项目，入驻市级孵化基地最高可获 300 平方米 3 年免费使用权。\n【相关链接】https://www.gdqy.gov.cn',NULL,'数智游民创新工场','0','0',1,'2026-08-21 12:46:32','admin','2026-08-21 12:46:32','',NULL),(10,5,'《关于促进省职教城清远高新区凤翔谷发展的若干措施（试行）》','大学毕业生到高新区孵化载体创办企业，最长 24 个月场租补贴（20 元/㎡/月，最高 200㎡）。','【政策名称】《关于促进省职教城清远高新区凤翔谷发展的若干措施（试行）》\n【发文级别】清远高新区\n【状态】已实施\n【政策要点】大学毕业生到省职教城清远高新区孵化载体创办企业，给予最长 24 个月场租补贴，标准为 20 元/平方米/月，最大补贴面积不超过 200 平方米。\n【相关链接】https://www.gdqy.gov.cn',NULL,'数智游民创新工场','0','0',1,'2026-08-21 12:46:32','admin','2026-08-21 12:46:32','',NULL),(11,5,'《广东省支持人工智能 OPC 创新发展行动方案（2026—2028年）》','粤发改高技〔2026〕78 号：2028 年建成 100 个 OPC 生态社区、培育 1000 家标杆企业、集聚 10000 名人才。','【政策名称】《广东省支持人工智能 OPC 创新发展行动方案（2026—2028年）》\n【发文级别】省级\n【文号】粤发改高技〔2026〕78 号\n【印发时间】2026 年 3 月 13 日\n【状态】已出台（主动公开）\n【总体目标】2026 年先行培育 10 个具有引领效应的人工智能 OPC 生态社区，形成一批年营业收入超千万的优质企业；到 2028 年，建成百个人工智能 OPC 生态社区，培育千家标杆企业，集聚万名创新创业人才，将广东打造成为全国领先的人工智能 OPC 发展高地。\n【六大任务】一、加强基础能力保障：算力券制度、算力公共服务平台、\"政府—社区—平台—OPC\"联动机制、公共数据开放与授权运营、免费模型接口与安全合规检测的公共模型服务平台；二、完善空间载体配套：打造\"拎脑入驻\"的 OPC 生态社区并给予算力补贴、省级社区认定评估、传统孵化器转型；三、推动场景开放创新：构建短剧短视频/电子商务/知识付费/数字文创/软件开发场景池、湾区应用场景发布厅、以赛促创（琶洲算法大赛）、跨境应用场景；四、拓宽多元融资渠道：创投基金矩阵（大湾区国家创投引导基金等）、\"人才贷/研发贷/成果贷/算力贷\"全周期信贷产品；五、强化人才政策供给：OPC 人才纳入高层次人才认定、高校\"人工智能+\"交叉学科、人工智能训练师职业技能等级认定、创业导师专家库、人才安居（\"一张床、一间房、一套房\"）；六、健全服务保障体系：企业开办\"一日办结、一网通办\"、知识产权质押处置、调解/公证/仲裁特色法律服务、人工智能应用中试基地、企业出海一站式服务（ODI 备案、跨境支付）。\n【原文链接】广东省政府门户网站：https://www.gd.gov.cn；广东省科技厅：https://gdstc.gd.gov.cn',NULL,'数智游民创新工场','1','0',13,'2026-08-21 12:46:32','admin','2026-08-21 12:46:32','',NULL),(12,5,'《清远市加快数字政府领域通用人工智能应用若干政策措施》（征求意见稿）','酝酿中政策：2024 年 1 月已结束意见征集，尚未正式出台。','【政策名称】《清远市加快数字政府领域通用人工智能应用若干政策措施》（征求意见稿）\n【发文级别】清远市级\n【状态】酝酿中（2024 年 1 月已结束意见征集，尚未正式出台）\n【政策方向】加快数字政府领域通用人工智能应用，为 AI 企业参与数字政府建设提供政策指引。\n【相关报道】https://qysme.com',NULL,'数智游民创新工场','0','0',2,'2026-08-21 12:46:32','admin','2026-08-21 12:46:32','',NULL),(13,1,'广东出台行动方案：到 2028 年建成 100 个 AI OPC 生态社区','粤发改高技〔2026〕78 号发布，培育 1000 家标杆企业、集聚 10000 名创新创业人才，算力券、人才贷、训练师认定等支持全面覆盖。','2026 年 3 月，广东省发展改革委印发《广东省支持人工智能 OPC 创新发展行动方案（2026—2028年）》（粤发改高技〔2026〕78 号）。方案提出：2026 年先行培育 10 个具有引领效应的人工智能 OPC 生态社区；到 2028 年建成百个生态社区、培育千家标杆企业、集聚万名创新创业人才。支持内容覆盖算力券补贴、\"拎脑入驻\"、全周期信贷（人才贷/研发贷/成果贷/算力贷）、人工智能训练师职业技能等级认定、人才安居保障等。\"数智游民创新工场\"作为清远市首个人工智能 OPC 生态社区，将率先对接省级政策资源，为入驻企业提供一站式政策服务。',NULL,'数智游民创新工场','1','0',3,'2026-08-20 12:46:32','admin','2026-08-21 12:46:32','',NULL),(14,1,'清远高新区开通 AI OPC 登记注册绿色通道','\"一窗通办\"\"一日办结\"，探索\"集群注册\"等无需实体地址的注册模式，破解工位注册、地址挂靠堵点。','清远高新区第十二期政企恳谈会明确：设立人工智能 OPC 登记注册\"明晰指引\"和\"绿色通道\"，实行\"一窗通办\"\"一日办结\"；探索\"集群注册\"等无需实体地址的注册模式，为数字游民与一人公司创业者破解\"工位注册\"\"地址挂靠\"等落地堵点。依托清远星谷科技园布局的 AI 创客试点，\"拎脑入驻\"正在成为现实。',NULL,'数智游民创新工场','0','0',0,'2026-08-18 12:46:32','admin','2026-08-21 12:46:32','',NULL),(15,1,'省市共建孵化基地免租 3-4 年：OPC 项目最高 300㎡ 三年免费','凤翔谷措施同步为大学毕业生创业企业提供最长 24 个月场租补贴（20 元/㎡/月，最高 200㎡）。','清远市省市共建创业孵化基地面向创业团队开放，享受 3 至 4 年免租金支持；符合条件的 OPC 项目入驻市级孵化基地，最高可获 300 平方米 3 年免费使用权。《关于促进省职教城清远高新区凤翔谷发展的若干措施（试行）》同步实施：大学毕业生到高新区孵化载体创办企业，给予最长 24 个月场租补贴，标准为 20 元/平方米/月，最大补贴面积不超过 200 平方米，进一步降低大学生 OPC 创业的场地成本。',NULL,'数智游民创新工场','0','0',0,'2026-08-16 12:46:32','admin','2026-08-21 12:46:32','',NULL);
